def parse_duration(s):
    """解析 "1h30m" 这类时长字符串，返回分钟数"""
    total = 0
    num = ""
    for ch in s:
        if ch.isdigit():
            num += ch
        else:
            if ch == "h":
                total += int(num) * 60
            elif ch == "m":
                total += int(num)
            num = ""
    return total

